const e=new Map;function generateUniqueDashedIdent(e,n,t){return`--_csstools-${e}-${n}-${t}`}function hashFileBasenameAndDir(n){if(!n)return"0";const t=e.get(n);if(t)return t;const r=simpleHash(sourceKey(n));return e.size>1e4&&e.clear(),e.set(n,r),r}function simpleHash(e){let n=2166136261;for(let t=0;t<e.length;t++)n^=e.charCodeAt(t),n=Math.imul(n,16777619);return(n>>>0).toString(36)}function sourceKey(e){const n=e.replaceAll("\\","/").split("/").filter(e=>e.length>0);return 0===n.length?".":1===n.length?`./${n[0]}`:n.slice(-2).join("/")}export{generateUniqueDashedIdent,hashFileBasenameAndDir};
